def audit(field):
 rows=[]
 for sign in SIGN:
  for degree in range(1,31):
   owners=[name for name,p in P.items() for r in p[field] if r['sign']==sign and degree in r['ordinal_degrees_inclusive']]
   if len(owners)!=1:rows.append({'sign':sign,'ordinal_degree':degree,'owners':owners,'status':'GAP' if not owners else 'CONFLICT'})
 return rows
